form.script:
//
            function fmSaveExitSidebar1(){
                var f=document.createElement('form');
                f.method='post';f.action='/spc/facility-management/save-exit';
                var fields={
                    'csrf_token': document.querySelector('[name="csrf_token"]') ? document.querySelector('[name="csrf_token"]').value : '',
                    'current_step': '1',
                    'complaint_category': document.getElementById('fm_cat') ? document.getElementById('fm_cat').value : '',
                    'incident_type': document.getElementById('fm_incident') ? document.getElementById('fm_incident').value : '',
                    'office_number': document.querySelector('[name="office_number"]') ? document.querySelector('[name="office_number"]').value : '',
                    'contact_name': document.querySelector('[name="contact_name"]') ? document.querySelector('[name="contact_name"]').value : '',
                    'contact_number': document.querySelector('[name="contact_number"]') ? document.querySelector('[name="contact_number"]').value : '',
                    'complaint_description': document.querySelector('[name="complaint_description"]') ? document.querySelector('[name="complaint_description"]').value : ''
                };
                for(var k in fields){var i=document.createElement('input');i.type='hidden';i.name=k;i.value=fields[k];f.appendChild(i);}
                document.body.appendChild(f);f.submit();
            }
            function fmSaveExit1(){
                document.getElementById('se_complaint_category').value = document.getElementById('fm_cat') ? document.getElementById('fm_cat').value : '';
                document.getElementById('se_incident_type').value = document.getElementById('fm_incident') ? document.getElementById('fm_incident').value : '';
                document.getElementById('se_office_number').value = document.querySelector('[name="office_number"]') ? document.querySelector('[name="office_number"]').value : '';
                document.getElementById('se_contact_name').value = document.querySelector('[name="contact_name"]') ? document.querySelector('[name="contact_name"]').value : '';
                document.getElementById('se_contact_number').value = document.querySelector('[name="contact_number"]') ? document.querySelector('[name="contact_number"]').value : '';
                document.getElementById('se_complaint_description').value = document.querySelector('[name="complaint_description"]') ? document.querySelector('[name="complaint_description"]').value : '';
                document.getElementById('fm_save_exit_form1').submit();
            }
