body.script:
//
var FM_INCIDENTS = {
    'electrical': ['Light not working','Light Blinking','Power socket not working','Breaker trip off'],
    'air_conditioning': ['AC not working','Less cooling','Noising indoor unit','AC leakage'],
    'fire_alarm': ['Sprinkler','Emergency Light','Other'],
    'general': ['Door Issues','Lock Issues','Wall Issues','Ceiling Issues']
};
function fmCatChange(v){
    var section = document.getElementById('fm_incident_section');
    var sel = document.getElementById('fm_incident');
    if(v && FM_INCIDENTS[v]){
        section.style.display = 'block';
        sel.innerHTML = '<option value="">Incident type</option>';
        FM_INCIDENTS[v].forEach(function(opt){
            var o = document.createElement('option');
            o.value = opt.toLowerCase().replace(/ /g,'_');
            o.textContent = opt;
            sel.appendChild(o);
        });
    } else {
        section.style.display = 'none';
    }
}
function fmFileSelected(input){
    if(input.files && input.files[0]){
        document.getElementById('uploaded_file_info').style.display='flex';
        document.getElementById('uploaded_file_name').textContent=input.files[0].name;
        document.getElementById('upload_box').style.borderColor='#1abc9c';
    }
}
function fmRemoveFile(){
    document.getElementById('doc_image').value='';
    document.getElementById('uploaded_file_info').style.display='none';
    document.getElementById('upload_box').style.borderColor='#1a2340';
}
function fmStep1Validate(){
  var valid=true;
  function showErr(id,msg){var el=document.getElementById(id);if(!el){el=document.createElement("div");el.id=id;el.style.cssText="color:red;font-size:12px;margin-top:4px";}el.textContent=msg;el.style.display="block";}
  function hideErr(id){var el=document.getElementById(id);if(el)el.style.display="none";}
  function addErr(f,id){if(f){if(!document.getElementById(id)){var e=document.createElement("div");e.id=id;e.style.cssText="color:red;font-size:12px;margin-top:4px";f.insertAdjacentElement("afterend",e);}}}
  var cat=document.querySelector('[name="complaint_category"]');addErr(cat,"fm_cat_err");
  if(!cat){showErr("fm_cat_err","Please select a complaint category.");valid=false;}else{if(!cat.value){showErr("fm_cat_err","Please select a complaint category.");valid=false;}else hideErr("fm_cat_err");}
  var inc=document.querySelector('[name="incident_type"]');
  var incSec=document.getElementById('fm_incident_section');
  if(incSec){if(incSec.style.display!=='none'){addErr(inc,"fm_inc_err");if(!inc){showErr("fm_inc_err","Please select an incident type.");valid=false;}else{if(!inc.value){showErr("fm_inc_err","Please select an incident type.");valid=false;}else hideErr("fm_inc_err");}}}
  var img=document.querySelector('[name="doc_image"]');
  if(img){if(!img.files||img.files.length===0){if(!document.getElementById("fm_img_err")){var e=document.createElement("div");e.id="fm_img_err";e.style.cssText="color:red;font-size:12px;margin-top:4px";img.parentElement.insertAdjacentElement("afterend",e);}document.getElementById("fm_img_err").textContent="Please upload an image.";document.getElementById("fm_img_err").style.display="block";valid=false;}else{var el=document.getElementById("fm_img_err");if(el)el.style.display="none";}}
  var on=document.querySelector('[name="office_number"]');addErr(on,"fm_on_err");
  if(!on){showErr("fm_on_err","Please enter office number.");valid=false;}else{if(!on.value.trim()){showErr("fm_on_err","Please enter office number.");valid=false;}else hideErr("fm_on_err");}
  var cn=document.querySelector('[name="contact_name"]');addErr(cn,"fm_cn_err");
  if(!cn){showErr("fm_cn_err","Please enter contact name.");valid=false;}else{if(!cn.value.trim()){showErr("fm_cn_err","Please enter contact name.");valid=false;}else hideErr("fm_cn_err");}
  var cp=document.querySelector('[name="contact_number"]');addErr(cp,"fm_cp_err");
  var cpv=cp?cp.value.trim().replace(new RegExp("[^0-9]","g"),""):"";
  if(cpv.length===0){showErr("fm_cp_err","Please enter a valid contact number.");valid=false;}else hideErr("fm_cp_err");
  var desc=document.querySelector('[name="complaint_description"]');addErr(desc,"fm_desc_err");
  if(!desc){showErr("fm_desc_err","Please enter complaint description.");valid=false;}else{if(!desc.value.trim()){showErr("fm_desc_err","Please enter complaint description.");valid=false;}else hideErr("fm_desc_err");}
  if(valid)document.getElementById("fm_main_form1").submit();
}

