function fmSaveExitStep2(){
                var f=document.createElement('form');
                f.method='post';f.action='/spc/facility-management/save-exit';
                var csrf=document.querySelector('[name="csrf_token"]');
                var cb=document.querySelector('[name="declaration_accepted"]');
                var fields={'csrf_token':csrf?csrf.value:'','current_step':'2','declaration_accepted':cb&&cb.checked?'on':'off'};
                for(var k in fields){var i=document.createElement('input');i.type='hidden';i.name=k;i.value=fields[k];f.appendChild(i);}
                document.body.appendChild(f);f.submit();
            }
            function fmDeclValidate(){
  var cb=document.querySelector('[name="declaration_accepted"]');
  if(!cb||!cb.checked){
    if(!document.getElementById("fm_decl_err")){var e=document.createElement("div");e.id="fm_decl_err";e.style.cssText="color:red;font-size:12px;margin-top:8px";cb.parentElement.insertAdjacentElement("afterend",e);}
    document.getElementById("fm_decl_err").textContent="Please accept the declaration to continue.";
    document.getElementById("fm_decl_err").style.display="block";
    return;
  }
  var el=document.getElementById("fm_decl_err");if(el)el.style.display="none";
  document.querySelector("form").submit();
}
function fmSaveExitStep3(){
    var f=document.createElement('form');
    f.method='post';f.action='/spc/facility-management/save-exit';
    var csrf=document.querySelector('[name="csrf_token"]');
    var fields={'csrf_token':csrf?csrf.value:'','current_step':'3'};
    for(var k in fields){var i=document.createElement('input');i.type='hidden';i.name=k;i.value=fields[k];f.appendChild(i);}
    document.body.appendChild(f);f.submit();
}
